/**
 * Seeds holdings for all model portfolios where the DB has fewer holdings than static data.
 * Safe to run multiple times — only updates if DB count < static count.
 */
export async function seedModelPortfolioHoldings(): Promise<void> {
  let updated = 0;
  let skipped = 0;
  let errors = 0;

  for (const [portfolioId, holdings] of Object.entries(PORTFOLIO_HOLDINGS_SEED)) {
    try {
      // Fetch current DB holdings count
      const rows = await db.select({ id: modelPortfolios.id, holdings: modelPortfolios.holdings })
        .from(modelPortfolios)
        .where(eq(modelPortfolios.id, portfolioId))
        .limit(1);

      if (!rows[0]) { skipped++; continue; } // Portfolio not in DB yet

      const currentHoldings = Array.isArray(rows[0].holdings) ? rows[0].holdings : [];
      if (currentHoldings.length >= holdings.length) { skipped++; continue; } // Already seeded

      // Update with canonical holdings
      await db.update(modelPortfolios)
        .set({
          holdings: holdings as any,
          updatedAt: new Date(),
        })
        .where(eq(modelPortfolios.id, portfolioId));

      console.log(`  ✅ [Holdings Seed] ${portfolioId}: ${holdings.length} holdings written (was ${currentHoldings.length})`);
      updated++;
    } catch (err: unknown) {
      console.warn(`  ⚠️  [Holdings Seed] ${portfolioId} failed:`, err instanceof Error ? err.message : String(err));
      errors++;
    }
  }

  console.log(`[Holdings Seed] Complete — updated: ${updated}, skipped: ${skipped}, errors: ${errors}`);
}
